sys_ui_page.processing_script:
/**
 * Processing script for x_cmdbgov_app_dash.do.
 *
 * Runs server-side only when the page is submitted (POST) through the
 * <g:ui_form> in dash.html. Its single job is to queue an assessment run for
 * an administrator; the async business rule on x_cmdbgov_app_run then
 * executes it.
 *
 * The submitted field is gov_action=queue_run, carried by the submit button's
 * own name/value pair. UI page processing scripts expose posted fields as bare
 * globals (as in the platform's own documented example), and request
 * .getParameter is also available in some contexts, so both are read.
 *
 * The role is re-checked here and never trusted from the form: hiding the
 * button is only cosmetic, this check plus the create ACL is the real control.
 *
 * This is the one and only write reachable from the dashboard.
 */
;(function () {
    var action = ''

    // Posted field as a bare global - the documented UI page behaviour.
    try {
        if (typeof gov_action !== 'undefined' && gov_action) {
            action = '' + gov_action
        }
    } catch (eGlobal) {
        action = ''
    }

    // Fall back to the request object where it is available.
    if (!action) {
        try {
            action = '' + (request.getParameter('gov_action') || '')
        } catch (eRequest) {
            action = ''
        }
    }

    if (action !== 'queue_run') {
        // A plain GET, or a submit we do not recognise: just show the page.
        return
    }

    if (!gs.hasRole('x_cmdbgov_app.admin')) {
        gs.addErrorMessage(gs.getMessage('You need the CMDB Governance admin role to queue an assessment.'))
        return
    }

    try {
        var run = new GlideRecord('x_cmdbgov_app_run')
        run.initialize()
        run.setValue('state', 'queued')
        var sysId = run.insert()

        if (sysId) {
            gs.addInfoMessage(
                gs.getMessage(
                    'Assessment queued. It normally finishes within a few seconds -- reload this page to see the new scores.'
                )
            )
            return
        }
        gs.addErrorMessage(gs.getMessage('The assessment run could not be queued.'))
    } catch (e) {
        gs.error('CMDB Governance dashboard could not queue a run: ' + (e.message || e))
        gs.addErrorMessage(gs.getMessage('The assessment run could not be queued: ' + (e.message || e)))
    }
})()
